const m = require("./repo/src/mailer.js");
const ev = { id: "evt-closed-1", type: "ticket.closed" };
const row = m.handle(ev);
if (!row) throw new Error("ticket.closed should enqueue");
if (row.eventId !== ev.id) throw new Error("must key on event.id");
if (row.type !== "ticket.closed") throw new Error("type mismatch");
const dup = m.handle(ev);
if (dup !== row) throw new Error("same event.id must reuse existing row");
if (m.countFor("ticket.closed") !== 1) throw new Error("dedupe failed");
if (m.handle({ id: "x", type: "ticket.opened" }) !== null) throw new Error("only ticket.closed");
m.failSend("evt-closed-1");
if (!m.outbox[0].failed) throw new Error("failSend should mark failed");
if (m.outbox.length !== 1) throw new Error("failed mail must stay in outbox");
const early = m.retry("evt-closed-1");
if (!early || early.status !== "wait") throw new Error("retry-backoff must wait, got " + JSON.stringify(early));
if (m.outbox[0].failed !== true) throw new Error("waited retry must not send");
m.outbox[0].retryAt = Date.now() - 1;
const late = m.retry("evt-closed-1");
if (!late || late.status !== "sent") throw new Error("elapsed backoff should send, got " + JSON.stringify(late));
if (m.outbox[0].failed !== false) throw new Error("successful retry should clear failed");
console.log("verify-mail retry-closed: pass");
console.log(JSON.stringify({ count: m.countFor("ticket.closed"), backoffMs: m.backoffMs(), outbox: m.outbox }));
'
